import Selectors from "block_myteams/local/selectors";
import {createConversationWithUser} from 'core_message/message_drawer_helper';

let initialized = false;

/**
 * Initialize the block.
 */
export const init = () => {

    if (initialized) {
        // We already added the event listeners (can be called multiple times by mustache template).
        return;
    }

    // Listen to all click events in the DOM.
    document.addEventListener('click', (event) => {
        // The "Send message" button was clicked.
        const sendMessage = event.target.closest(Selectors.actions.sendMessage);
        if (sendMessage) {
            event.preventDefault();
            createConversationWithUser({userid: parseInt(sendMessage.dataset.userid)});
        }
        // The "Show more" button was clicked.
        const showMoreButton = event.target.closest(Selectors.actions.showMore);
        if (showMoreButton) {
            const itemsList = showMoreButton.closest(Selectors.regions.userinfoSectionItems);
            itemsList.classList.remove('show-more-list');
            showMoreButton.remove();
        }
    });

    initialized = true;
};
